const kodlar = { 
    "H": "Halkalı", 
    "G": "Gebze", 
    "A": "Ataköy", 
    "P": "Pendik", 
    "Z": "Zeytinburnu", 
    "N": "Hafta Sonu Gece" 
};

export function getLiveTrainsForStation(stationIdx, directionIdx) {
    const key = DURAK_KEYS[stationIdx];
    if (!key || !durakVerileri[key]) return [];

    const stationData = durakVerileri[key];
    const liste = directionIdx === 1 ? stationData.gYonu : stationData.hYonu; // 1 = Gebze, 0 = Halkalı
    if (!liste || liste.length === 0) return [];

    const simdi = new Date();
    let suanDakika = simdi.getHours() * 60 + simdi.getMinutes();

    if (suanDakika < 240) {
        suanDakika += 1440;
    }

    const islenmisListe = liste.map(item => {
        const [saatStr, kod] = item.split('/');
        const [h, m] = saatStr.split(':').map(Number);
        let toplamDakika = h * 60 + m;
        
        if (toplamDakika < 240) toplamDakika += 1440;
        
        return { saatStr, kod, toplamDakika, isHalkaliDir: (directionIdx === 0), destination: kodlar[kod] || '' };
    });

    islenmisListe.sort((a, b) => a.toplamDakika - b.toplamDakika);

    let baslangicIndeksi = islenmisListe.findIndex(tren => tren.toplamDakika >= suanDakika);
    if (baslangicIndeksi === -1) baslangicIndeksi = 0;

    let siradakiTrenler = [];
    for (let i = 0; i < 6; i++) {
        const index = (baslangicIndeksi + i) % islenmisListe.length;
        const item = islenmisListe[index];
        const arrMin = item.toplamDakika - suanDakika; // Might be negative if wrapping around a full day, but for live it's correct
        siradakiTrenler.push({
            timeStr: item.saatStr,
            destination: item.destination,
            kod: item.kod,
            remainingMin: arrMin >= 0 ? arrMin : arrMin + 1440,
            isHalkaliDir: item.isHalkaliDir
        });
    }

    return siradakiTrenler;
}

// Dummy functions for exports that app.js still imports (to avoid crashes before we update app.js)
export const CUM_G2H = [];
export const CUM_H2G = [];
export const TOTAL_G2H = 0;
export const TOTAL_H2G = 0;
export const G2H_WEEKDAY = [];
export const H2G_WEEKDAY = [];
export const G2H_WEEKEND = [];
export const H2G_WEEKEND = [];

export function getNextTrains(idx, dirString) {
    if (dirString === 'G2H') return getLiveTrainsForStation(idx, 0); // Halkalı yönü
    if (dirString === 'H2G') return getLiveTrainsForStation(idx, 1); // Gebze Yönü
    
    // Fallback if no dirString
    return {
        halkali: getLiveTrainsForStation(idx, 0),
        gebze: getLiveTrainsForStation(idx, 1)
    };
}
export function getTrainPosition() { return { x: 0, y: 0 }; }
export function minsToHHMM(m) { 
    let hh = Math.floor(m/60)%24; 
    let mm = Math.floor(m%60); 
    return (hh<10?'0':'')+hh+':'+(mm<10?'0':'')+mm; 
}
